def semver_sort(versions):
    def parse_version(version):
        # Split build metadata
        if '+' in version:
            version, build = version.split('+', 1)
        else:
            build = ''

        # Split pre-release
        if '-' in version:
            core, prerelease = version.split('-', 1)
        else:
            core = version
            prerelease = None

        # Parse core version
        parts = core.split('.')
        major = int(parts[0]) if len(parts) > 0 else 0
        minor = int(parts[1]) if len(parts) > 1 else 0
        patch = int(parts[2]) if len(parts) > 2 else 0

        # Parse pre-release identifiers
        if prerelease is not None:
            prerelease_parts = prerelease.split('.')
            prerelease_tuple = []
            for part in prerelease_parts:
                if part.isdigit():
                    prerelease_tuple.append((0, int(part)))
                else:
                    prerelease_tuple.append((1, part))
            prerelease_tuple = tuple(prerelease_tuple)
        else:
            prerelease_tuple = None

        return (major, minor, patch, prerelease_tuple)

    def sort_key(version):
        major, minor, patch, prerelease_tuple = parse_version(version)

        # For sorting: version without prerelease sorts after version with prerelease
        # So we use (major, minor, patch, has_prerelease, prerelease_tuple)
        # where has_prerelease=0 if prerelease exists (sorts first), 1 if not
        if prerelease_tuple is None:
            # No prerelease: sorts after same version with prerelease
            return (major, minor, patch, 1, ())
        else:
            # Has prerelease: sorts before same version without prerelease
            return (major, minor, patch, 0, prerelease_tuple)

    # Sort using the key function, maintaining input order for equal elements
    indexed_versions = list(enumerate(versions))
    indexed_versions.sort(key=lambda x: (sort_key(x[1]), x[0]))

    return [v for _, v in indexed_versions]

